        public int apply_cb()
        {
            int errorCode = 0;
            try
            {
                // 1. Safety Check: Make sure a part is open!
                if (!NXSessionManager.EnsureWorkPartExists()) return 1;

                // 2. Create the "Save State" (Undo Mark)
                Session.UndoMarkId markId = NXSessionManager.SetUndoMark("Generate Spur Gear");

                try
                {
                    // 3. Extract LIVE inputs from your custom UI blocks
                    int teeth = blockTeeth.Value;
                    double moduleVal = blockModule.Value;
                    double facewidth = blockFaceWidth.Value;
                    double pressureAngleDeg = blockPressureAngle.Value;
