                    // Pack them into your Data Object (The Box)
                    GearParameters myGearData = new GearParameters(teeth, moduleVal, facewidth, pressureAngleDeg, shaftHoleDia);

                    // Validate the inputs (The Bouncer)
                    GearValidator.Validate(myGearData);

                    // Build the gear! (The Engine)
                    SpurGearBuilder.BuildGear(NXSessionManager.WorkPart, myGearData);

                    return 0; // Success! NX will automatically keep the geometry.
                }
                catch (Exception ex)
                {
                    // 4. THE SAFETY NET: If ANYTHING above fails, roll back the NX file instantly.
                    NXSessionManager.UndoToMark(markId, "Generate Spur Gear");

                    // Tell the user exactly what went wrong without breaking the file
                    NXSessionManager.ShowMessage("Gear Generation Failed", ex.Message, NXMessageBox.DialogType.Error);
                    return 1;
                }
            }
            catch (Exception ex)
            {
                // Absolute fallback for major system errors
                errorCode = 1;
                UI.GetUI().NXMessageBox.Show("Block Styler Error", NXMessageBox.DialogType.Error, ex.ToString());
            }
            return errorCode;
        }

